contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address recipient, uint amount) public payable {
        require(address(this).balance >= amount);
        c.f{value: amount}(recipient);
        uint balAfter = address(c).balance;
        address currentOwner = c.owner();
        if (currentOwner == address(this)) {
            uint beforeBal = address(c).balance;
            c.withdrawAll(recipient);
            assert(address(c).balance == 0 && balAfter >= beforeBal);
